`include "prim_assert.sv"

module sram2tlul #(
  parameter int                        SramAw = 12,
  parameter int                        SramDw = 32,
  parameter logic [top_pkg::TL_AW-1:0] TlBaseAddr = 'h0  // Base address of SRAM request
) (
  input clk_i,
  input rst_ni,

  output tlul_pkg::tl_h2d_t tl_o,
  input  tlul_pkg::tl_d2h_t tl_i,

  // SRAM
  input                     mem_req_i,
  input                     mem_write_i,
  input        [SramAw-1:0] mem_addr_i,
  input        [SramDw-1:0] mem_wdata_i,
  output logic              mem_rvalid_o,
  output logic [SramDw-1:0] mem_rdata_o,
  output logic        [1:0] mem_error_o
);

  import tlul_pkg::*;

  `ASSERT_INIT(wrongSramDw, SramDw == top_pkg::TL_DW)

  localparam int unsigned SRAM_DWB = $clog2(SramDw/8);

  assign tl_o.a_valid   = mem_req_i;
  assign tl_o.a_opcode  = (mem_write_i) ? PutFullData : Get;
  assign tl_o.a_param   = '0;
  assign tl_o.a_size    = top_pkg::TL_SZW'(SRAM_DWB); // Max Size always
  assign tl_o.a_source  = '0;
  assign tl_o.a_address = TlBaseAddr |
                          {{(top_pkg::TL_AW-SramAw-SRAM_DWB){1'b0}},mem_addr_i,{(SRAM_DWB){1'b0}}};
  assign tl_o.a_mask    = '1;
  assign tl_o.a_data    = mem_wdata_i;
  assign tl_o.a_user    = '0;

  assign tl_o.d_ready   = 1'b1;

  assign mem_rvalid_o   = tl_i.d_valid && (tl_i.d_opcode == AccessAckData);
  assign mem_rdata_o    = tl_i.d_data;
  assign mem_error_o    = {2{tl_i.d_error}};

  // below assertion fails when TL-UL doesn't accept request in a cycle,
  // which is currently not supported by sram2tlul
  `ASSERT(validNotReady, tl_o.a_valid |-> tl_i.a_ready)

endmodule

`include "prim_assert.sv"

module tlul_adapter_dmi
  import tlul_pkg::*;
#(
  parameter  bit CmdIntgCheck      = 1,  // 1: Enable command integrity check
  parameter  bit EnableRspIntgGen  = 1,  // 1: Generate response integrity
  parameter  bit EnableDataIntgGen = 1   // 1: Generate response data integrity
) (
  input clk_i,
  input rst_ni,

  // TL-UL interface
  input  tl_h2d_t tl_h2d_i,
  output tl_d2h_t tl_d2h_o,

  // control interface
  output logic    intg_error_o,

  output logic          dmi_req_valid_o,
  input  logic          dmi_req_ready_i,
  output dm::dmi_req_t  dmi_req_o,

  input  logic          dmi_resp_valid_i,
  output logic          dmi_resp_ready_o,
  input  dm::dmi_resp_t dmi_resp_i
);

  localparam int IdW = $bits(tl_h2d_i.a_source);
  localparam int SzW = $bits(tl_h2d_i.a_size);

  logic a_ack, d_ack;  // Indicates whether the corresponding valid/ready handshake completes.
  logic outstanding_q; // Indicates whether there is a pending request.
  assign a_ack   = tl_h2d_i.a_valid & tl_d2h_o.a_ready;
  assign d_ack   = tl_d2h_o.d_valid & tl_h2d_i.d_ready;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni)    outstanding_q <= 1'b0;
  else if (a_ack) outstanding_q <= 1'b1;
  else if (d_ack) outstanding_q <= 1'b0;
end

logic rd_req, wr_req;
assign wr_req  = tl_h2d_i.a_valid && ((tl_h2d_i.a_opcode == PutFullData) ||
                                      (tl_h2d_i.a_opcode == PutPartialData));
assign rd_req  = tl_h2d_i.a_valid && (tl_h2d_i.a_opcode == Get);

// If we detect an error, the response will be returned immediately in the next cycle
// and we do not send a request out to the DMI.
logic error_d, error_q;
assign dmi_req_valid_o = (wr_req || rd_req) && !error_d;
// The DMI response can be accepted if there is a pending request without error.
assign dmi_resp_ready_o = outstanding_q && !error_q;

// We expect a word-aligned address here, otherwise an error is returned (see further below).
assign dmi_req_o.addr = {2'b00, tl_h2d_i.a_address[top_pkg::TL_AW-1:2]};
assign dmi_req_o.data = tl_h2d_i.a_data;
assign dmi_req_o.op   = (wr_req) ? dm::DTM_WRITE :
                        (rd_req) ? dm::DTM_READ  : dm::DTM_NOP;

logic [IdW-1:0] reqid_q;
logic [SzW-1:0] reqsz_q;
tl_d_op_e       rspop_q;
logic wr_req_q, rd_req_q;

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    reqid_q  <= '0;
    reqsz_q  <= '0;
    rspop_q  <= AccessAck;
    error_q  <= 1'b0;
    wr_req_q <= 1'b0;
    rd_req_q <= 1'b0;
  end else if (a_ack) begin
    reqid_q <= tl_h2d_i.a_source;
    reqsz_q <= tl_h2d_i.a_size;
    // Return AccessAckData regardless of error
    rspop_q <= (rd_req) ? AccessAckData : AccessAck;
    rd_req_q <= rd_req;
    wr_req_q <= wr_req;
    error_q  <= error_d;
  end
end

logic error_resp;
assign error_resp = error_q || (dmi_resp_i.resp == dm::DTM_ERR);

tlul_pkg::tl_d2h_t tl_d2h_o_pre;
assign tl_d2h_o_pre = '{
  // We are ready to accept a request if there is no outstanding one and if the DMI is ready.
  a_ready:  dmi_req_ready_i && !outstanding_q,
  // A data response is valid if the DMI response is valid and we've got an outstanding request.
  // If the request resulted in an internal error, the error response is returned without a DMI
  // response, since the request to the DMI has been suppressed by the error.
  d_valid:  (dmi_resp_valid_i || error_q) && outstanding_q,
  d_opcode: rspop_q,
  d_param:  '0,
  d_size:   reqsz_q,
  d_source: reqid_q,
  d_sink:   '0,
  // Blank data upon error in the same way as other TL-UL adapters would in OpenTitan.
  d_data:   (rd_req_q && !(error_resp || wr_req_q)) ? dmi_resp_i.data : {top_pkg::TL_DW{1'b1}},
  d_user:   '0,
  d_error:  error_resp
};

// outgoing integrity generation
tlul_rsp_intg_gen #(
  .EnableRspIntgGen(EnableRspIntgGen),
  .EnableDataIntgGen(EnableDataIntgGen),
  .UserInIsZero(1'b1)
) u_rsp_intg_gen (
  .tl_i(tl_d2h_o_pre),
  .tl_o(tl_d2h_o)
);

logic intg_error;
if (CmdIntgCheck) begin : gen_cmd_intg_check
  logic intg_error_q;
  tlul_cmd_intg_chk u_cmd_intg_chk (
    .tl_i(tl_h2d_i),
    .err_o(intg_error)
  );

    assign intg_error_o = intg_error_q;
  end else begin : gen_no_cmd_intg_check
    assign intg_error = 1'b0;
    assign intg_error_o = 1'b0;
  end

  ////////////////////
  // Error Handling //
  ////////////////////

  logic addr_align_err;     // Size and alignment
  logic be_err;             // Byte enable error.
  logic malformed_meta_err; // User signal format error or unsupported
  logic tl_err;             // Common TL-UL error checker
  assign error_d = addr_align_err ||
                   be_err ||
                   malformed_meta_err ||
                   tl_err ||
                   intg_error;

  // addr_align_err
  //    Raised if addr isn't aligned with the size
  //    Read size error is checked in tlul_assert.sv
  //    Here is it added due to the limitation of register interface.
  //    Only word-align is accepted based on comportability spec.
  assign addr_align_err = (wr_req) && |tl_h2d_i.a_address[1:0];

  // The DMI does not support a non-all-ones byte enable.
  assign be_err = (wr_req) && !(&tl_h2d_i.a_mask);

  // Don't allow unsupported values.
  assign malformed_meta_err = tl_a_user_chk(tl_h2d_i.a_user);

  // tl_err : separate checker
  tlul_err u_err (
    .clk_i,
    .rst_ni,
    .tl_i(tl_h2d_i),
    .err_o (tl_err)
  );

  `ASSERT_INIT(DwMatchedWithDm_A, top_pkg::TL_DW == $bits(dmi_req_o.data))

endmodule : tlul_adapter_dmi

`include "prim_assert.sv"

module tlul_adapter_host
  import tlul_pkg::*;
  import prim_mubi_pkg::mubi4_t;
#(
  parameter int unsigned MAX_REQS = 2,
  parameter bit EnableDataIntgGen = 0,
  parameter bit EnableRspDataIntgCheck = 0
) (
  input clk_i,
  input rst_ni,

  input                              req_i,
  output logic                       gnt_o,
  input  logic [top_pkg::TL_AW-1:0]  addr_i,
  input  logic                       we_i,
  input  logic [top_pkg::TL_DW-1:0]  wdata_i,
  input  logic [DataIntgWidth-1:0]   wdata_intg_i,
  input  logic [top_pkg::TL_DBW-1:0] be_i,
  input  mubi4_t                     instr_type_i,
  input  logic [RsvdWidth-1:0]       user_rsvd_i,

  output logic                       valid_o,
  output logic [top_pkg::TL_DW-1:0]  rdata_o,
  output logic [DataIntgWidth-1:0]   rdata_intg_o,
  output logic                       err_o,
  output logic                       intg_err_o,

  output tl_h2d_t                    tl_o,
  input  tl_d2h_t                    tl_i
);
  localparam int unsigned WordSize = $clog2(top_pkg::TL_DBW);

  logic [top_pkg::TL_AIW-1:0] tl_source;
  logic [top_pkg::TL_DBW-1:0] tl_be;
  tl_h2d_t                    tl_out;

  if (MAX_REQS == 1) begin : g_single_req
    assign tl_source = '0;
  end else begin : g_multiple_reqs
    localparam int ReqNumW  = $clog2(MAX_REQS);
    localparam int unsigned MaxSource = MAX_REQS - 1;
    localparam logic [ReqNumW-1:0] ReqNumOne = ReqNumW'(1'b1);

    logic [ReqNumW-1:0] source_d;
    logic [ReqNumW-1:0] source_q;

always_comb begin
  source_d = source_q;

  if (req_i && gnt_o) begin
    if (source_q == MaxSource[ReqNumW-1:0]) begin
      source_d = '0;
    end else  begin
      source_d = source_q + ReqNumOne;
    end
  end
end

  assign tl_source = top_pkg::TL_AIW'(source_q);
end

// For TL-UL Get opcode all active bytes must have their mask bit set, so all reads get all tl_be
// bits set. For writes the supplied be_i is used as the mask.
assign tl_be = ~we_i ? {top_pkg::TL_DBW{1'b1}} : be_i;

assign tl_out = '{
  a_valid:   req_i,
  a_opcode:  (~we_i) ? Get           :
             (&be_i) ? PutFullData   :
                       PutPartialData,
  a_param:   3'h0,
  a_size:    top_pkg::TL_SZW'(WordSize),
  a_mask:    tl_be,
  a_source:  tl_source,
  a_address: {addr_i[31:WordSize], {WordSize{1'b0}}},
  a_data:    wdata_i,
  a_user:    '{default: '0, data_intg: wdata_intg_i, instr_type: instr_type_i, rsvd: user_rsvd_i},
  d_ready:   1'b1
};

tlul_cmd_intg_gen #(.EnableDataIntgGen (EnableDataIntgGen)) u_cmd_intg_gen (
  .tl_i(tl_out),
  .tl_o(tl_o)
);

assign gnt_o        = tl_i.a_ready;

assign valid_o      = tl_i.d_valid;
assign rdata_o      = tl_i.d_data;
assign rdata_intg_o = tl_i.d_user.data_intg;

logic intg_err;
tlul_rsp_intg_chk #(
  .EnableRspDataIntgCheck(EnableRspDataIntgCheck)
) u_rsp_chk (
  .tl_i,
  .err_o(intg_err)
);

logic intg_err_q;

  assign err_o   = tl_i.d_error | intg_err;

  // intg_err_o is permanent once detected, and should be used
  // to trigger alerts
  assign intg_err_o = intg_err_q | intg_err;

  // Addresses are assumed to be word-aligned, and the bottom bits are ignored
  logic unused_addr_bottom_bits;
  assign unused_addr_bottom_bits = ^addr_i[WordSize-1:0];

  // Explicitly ignore unused fields of tl_i
  logic unused_tl_i_fields;
  assign unused_tl_i_fields = ^{tl_i.d_opcode, tl_i.d_param,
                                tl_i.d_size, tl_i.d_source, tl_i.d_sink,
                                tl_i.d_user};

`ifdef INC_ASSERT
  //VCS coverage off
  // pragma coverage off
  localparam int OutstandingReqCntW =
    (MAX_REQS == 2 ** $clog2(MAX_REQS)) ? $clog2(MAX_REQS) + 1 : $clog2(MAX_REQS);
  localparam logic [OutstandingReqCntW-1:0] OutstandingReqCntOne = OutstandingReqCntW'(1'b1);

  logic [OutstandingReqCntW-1:0] outstanding_reqs_q;
  logic [OutstandingReqCntW-1:0] outstanding_reqs_d;

always_comb begin
  outstanding_reqs_d = outstanding_reqs_q;

  if ((req_i && gnt_o) && !valid_o) begin
    outstanding_reqs_d = outstanding_reqs_q + OutstandingReqCntOne;
  end else if (!(req_i && gnt_o) && valid_o) begin
    outstanding_reqs_d = outstanding_reqs_q - OutstandingReqCntOne;
  end
end

`include "prim_assert.sv"

/**
 * Tile-Link UL adapter with RACL support
 *
 * - It allows filtering TLUL requests based on their range using an allow-list approach. A request
 *   is allowed if its address matches a racl range which allows access for the racl role associated
 *   with this request.
 */
module tlul_adapter_racl
  import tlul_pkg::*;
  import prim_mubi_pkg::mubi4_t;
#(
  parameter bit EnableRacl             = 0,          // 1: Enable RACL checks on access
  parameter bit RaclErrorRsp           = EnableRacl, // 1: Return TLUL error on RACL errors
  parameter int RaclPolicySelNumRanges = 1           // Number of ranges with a RACL policy
) (
  input                                                          clk_i,
  input                                                          rst_ni,
  // TL-UL interface
  input  tlul_pkg::tl_h2d_t                                      tl_h2d_i,
  output tlul_pkg::tl_d2h_t                                      tl_d2h_o,
  output tlul_pkg::tl_h2d_t                                      tl_filtered_h2d_o,
  input  tlul_pkg::tl_d2h_t                                      tl_filtered_d2h_i,
  // RACL interface
  input  top_racl_pkg::racl_policy_vec_t                         racl_policies_i,
  output top_racl_pkg::racl_error_log_t                          racl_error_o,
  input  top_racl_pkg::racl_range_t [RaclPolicySelNumRanges-1:0] racl_policy_sel_ranges_i
);
  if (EnableRacl) begin : gen_racl_role_logic
    // Retrieve RACL role from user bits and one-hot encode that for the comparison bitmap
    top_racl_pkg::racl_role_t racl_role;
    assign racl_role = top_racl_pkg::tlul_extract_racl_role_bits(tl_h2d_i.a_user.rsvd);

    top_racl_pkg::racl_role_vec_t racl_role_vec;
    prim_onehot_enc #(
      .OneHotWidth( $bits(top_racl_pkg::racl_role_vec_t) )
    ) u_racl_role_encode (
      .in_i ( racl_role     ),
      .en_i ( 1'b1          ),
      .out_o( racl_role_vec )
    );

    logic rd_req, wr_req, racl_read_allowed, racl_write_allowed, racl_error;
    logic [RaclPolicySelNumRanges-1:0] range_read_allowed;
    logic [RaclPolicySelNumRanges-1:0] range_write_allowed;

for (genvar r = 0; r < RaclPolicySelNumRanges; r++) begin : gen_racl_range_check
  top_racl_pkg::racl_range_t range;
  top_racl_pkg::racl_policy_t policy;
  logic range_match;
  assign range = racl_policy_sel_ranges_i[r];
  assign policy = racl_policies_i[range.policy_sel];
  // Check if the address is within range
  assign range_match = range.enable
                       & tl_h2d_i.a_address >= range.base
                       & tl_h2d_i.a_address <= range.limit;
  // If address matches, lookup permissions for policy defined for this range
  assign range_read_allowed[r]  = range_match & |(policy.read_perm  & racl_role_vec);
  assign range_write_allowed[r] = range_match & |(policy.write_perm & racl_role_vec);
end

    assign racl_read_allowed  = |range_read_allowed;
    assign racl_write_allowed = |range_write_allowed;

    assign rd_req             = tl_h2d_i.a_valid & (tl_h2d_i.a_opcode == tlul_pkg::Get);
    assign wr_req             = tl_h2d_i.a_valid & (tl_h2d_i.a_opcode == tlul_pkg::PutFullData |
                                                    tl_h2d_i.a_opcode == tlul_pkg::PutPartialData);
    assign racl_error         = (rd_req & ~racl_read_allowed) | (wr_req & ~racl_write_allowed);
    assign racl_error_o.valid = racl_error & tl_d2h_o.a_ready;

    tlul_request_loopback #(
      .ErrorRsp ( RaclErrorRsp )
    ) u_loopback (
      .clk_i        ( clk_i             ),
      .rst_ni       ( rst_ni            ),
      .squash_req_i ( racl_error        ),
      .tl_h2d_i     ( tl_h2d_i          ),
      .tl_d2h_o     ( tl_d2h_o          ),
      .tl_h2d_o     ( tl_filtered_h2d_o ),
      .tl_d2h_i     ( tl_filtered_d2h_i )
    );

    // Collect RACL error information
    assign racl_error_o.overflow    = 1'b0;
    assign racl_error_o.read_access = tl_h2d_i.a_opcode == tlul_pkg::Get;
    assign racl_error_o.racl_role   = racl_role;
    assign racl_error_o.ctn_uid     = top_racl_pkg::tlul_extract_ctn_uid_bits(tl_h2d_i.a_user.rsvd);
    assign racl_error_o.request_address = tl_h2d_i.a_address;
  end else begin : gen_no_racl_role_logic
    // Pass through and default assignments
    assign tl_filtered_h2d_o = tl_h2d_i;
    assign tl_d2h_o          = tl_filtered_d2h_i;
    assign racl_error_o      = '0;

    // Some signals are not read when RACL is disabled
    logic unused_signals;
    assign unused_signals = ^racl_policy_sel_ranges_i;
  end

  // Not all RACL policies are used, even if RACL is enabled
  logic unused_policy_sel;
  assign unused_policy_sel = ^racl_policies_i;

  `ASSERT(RaclAdapterNumRanges, EnableRacl |-> RaclPolicySelNumRanges > 0)

  // Ensure that RACL signals are not undefined
  `ASSERT_KNOWN(RaclAdapterErrorKnown_A, racl_error_o.valid)

endmodule

`include "prim_assert.sv"

/**
 * Tile-Link UL adapter for Register interface
 *
 * ICEBOX(#15822): Note that due to some modules with special needs (like
 * the vendored-in RV_DM), this module has been extended so that it
 * supports use cases outside of the generated reg_top module. This makes
 * this adapter and its parameterization options a bit heavy.
 *
 * We should in the future come back to this and refactor / align the
 * module and its parameterization needs.
 */

module tlul_adapter_reg
  import tlul_pkg::*;
  import prim_mubi_pkg::mubi4_t;
#(
  parameter  bit CmdIntgCheck      = 0,  // 1: Enable command integrity check
  parameter  bit EnableRspIntgGen  = 0,  // 1: Generate response integrity
  parameter  bit EnableDataIntgGen = 0,  // 1: Generate response data integrity
  parameter  int RegAw             = 8,  // Width of register address
  parameter  int RegDw             = 32, // Shall be matched with TL_DW
  parameter  int AccessLatency     = 0,  // 0: same cycle, 1: next cycle
  localparam int RegBw             = RegDw/8
) (
  input clk_i,
  input rst_ni,

  // TL-UL interface
  input  tl_h2d_t tl_i,
  output tl_d2h_t tl_o,

  // control interface
  input  mubi4_t  en_ifetch_i,
  output logic    intg_error_o,

  // Register interface
  output logic             re_o,
  output logic             we_o,
  output logic [RegAw-1:0] addr_o,
  output logic [RegDw-1:0] wdata_o,
  output logic [RegBw-1:0] be_o,
  input                    busy_i,
  // The following two signals are expected
  // to be returned in AccessLatency cycles.
  input        [RegDw-1:0] rdata_i,
  // This can be a write or read error.
  input                    error_i
);

  `ASSERT_INIT(AllowedLatency_A, AccessLatency inside {0, 1})

  localparam int IW  = $bits(tl_i.a_source);
  localparam int SZW = $bits(tl_i.a_size);

  logic outstanding_q;    // Indicates current request is pending
  logic a_ack, d_ack, hold_d_ack, hold_d_valid;

  logic [RegDw-1:0] rdata, rdata_q;
  logic             error_q, error, err_internal, instr_error, intg_error;

  logic addr_align_err;     // Size and alignment
  logic tl_err;             // Common TL-UL error checker

  logic [IW-1:0]  reqid_q;
  logic [SZW-1:0] reqsz_q;
  tl_d_op_e       rspop_q;

  logic rd_req, wr_req;

  assign a_ack   = tl_i.a_valid & tl_o.a_ready;
  assign d_ack   = tl_o.d_valid & tl_i.d_ready & ~hold_d_ack;
  // Request signal
  assign wr_req  = a_ack & ((tl_i.a_opcode == PutFullData) | (tl_i.a_opcode == PutPartialData));
  assign rd_req  = a_ack & (tl_i.a_opcode == Get);

  assign we_o    = wr_req & ~err_internal;
  assign re_o    = rd_req & ~err_internal;
  assign wdata_o = tl_i.a_data;
  assign be_o    = tl_i.a_mask;

  if (RegAw <= 2) begin : gen_only_one_reg
    assign addr_o  = '0;
  end else begin : gen_more_regs
    assign addr_o  = {tl_i.a_address[RegAw-1:2], 2'b00}; // generate always word-align
  end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni)    outstanding_q <= 1'b0;
  else if (a_ack) outstanding_q <= 1'b1;
  else if (d_ack) outstanding_q <= 1'b0;
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    reqid_q <= '0;
    reqsz_q <= '0;
    rspop_q <= AccessAck;
  end else if (a_ack) begin
    reqid_q <= tl_i.a_source;
    reqsz_q <= tl_i.a_size;
    // Return AccessAckData regardless of error
    rspop_q <= (rd_req) ? AccessAckData : AccessAck ;
  end
end

  if (AccessLatency == 1) begin : gen_access_latency1
    logic wr_req_q, rd_req_q;

`ifdef VERILATOR
    typedef enum logic [1:0] {
      TlulBug002Idle,
      TlulBug002HoldResp,
      TlulBug002HoldBaseline,
      TlulBug002InjectLateError
    } tlul_bug_002_state_e;

    int                   __tlul_bug_002_enabled;
    logic [2:0]           __tlul_bug_002_read_cnt_q;
    tlul_bug_002_state_e  __tlul_bug_002_state_q;
    logic                 __tlul_bug_002_late_error;

    initial begin
      __tlul_bug_002_enabled = 0;
      if ($test$plusargs("TLUL_BUG_002_INJECT")) begin
        __tlul_bug_002_enabled = 1;
      end
    end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    __tlul_bug_002_read_cnt_q <= '0;
    __tlul_bug_002_state_q <= TlulBug002Idle;
  end else begin
    if (__tlul_bug_002_state_q != TlulBug002Idle) begin
      unique case (__tlul_bug_002_state_q)
        TlulBug002HoldResp: begin
          __tlul_bug_002_state_q <= TlulBug002HoldBaseline;
        end
        TlulBug002HoldBaseline: begin
          __tlul_bug_002_state_q <= TlulBug002InjectLateError;
        end
        TlulBug002InjectLateError: begin
          __tlul_bug_002_state_q <= TlulBug002Idle;
        end
        default: begin
          __tlul_bug_002_state_q <= TlulBug002Idle;
        end
      endcase
    end else if (__tlul_bug_002_enabled && a_ack && rd_req) begin
      if (__tlul_bug_002_read_cnt_q < 3'h7) begin
        __tlul_bug_002_read_cnt_q <= __tlul_bug_002_read_cnt_q + 3'h1;
      end
      // Sink the existing directed witness window into the injection:
      // the target read is held in a synthetic backpressure window long
      // enough for rd_req_q to fall low before a one-cycle late error
      // pulse mutates the buffered response.
      if (__tlul_bug_002_read_cnt_q == 3'h2) begin
        __tlul_bug_002_state_q <= TlulBug002HoldResp;
      end
    end
  end
end

    assign hold_d_ack = (__tlul_bug_002_state_q == TlulBug002HoldResp) ||
                        (__tlul_bug_002_state_q == TlulBug002HoldBaseline);
    assign hold_d_valid = (__tlul_bug_002_state_q == TlulBug002HoldResp) ||
                          (__tlul_bug_002_state_q == TlulBug002HoldBaseline);
    assign __tlul_bug_002_late_error =
        (__tlul_bug_002_state_q == TlulBug002InjectLateError);
`else
    assign hold_d_ack = 1'b0;
    assign hold_d_valid = 1'b0;
`endif

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    rdata_q  <= '0;
    error_q  <= 1'b0;
    wr_req_q <= 1'b0;
    rd_req_q <= 1'b0;
  end else begin
    rd_req_q <= rd_req;
    wr_req_q <= wr_req;
    // Addressing phase
    if (a_ack) begin
      error_q <= err_internal;
    // Response phase
    end else begin
      error_q <= error;
      rdata_q <= rdata;
    end
  end
end

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    rdata_q <= '0;
    error_q <= 1'b0;
  end else if (a_ack) begin
    rdata_q <= (error_i || err_internal || wr_req) ? '1 : rdata_i;
    error_q <= error_i || err_internal;
  end
end

  assign rdata = rdata_q;
  assign error = error_q;
end

tlul_pkg::tl_d2h_t tl_o_pre;
assign tl_o_pre = '{
  a_ready:  ~(outstanding_q | busy_i),
  d_valid:  outstanding_q & ~hold_d_valid,
  d_opcode: rspop_q,
  d_param:  '0,
  d_size:   reqsz_q,
  d_source: reqid_q,
  d_sink:   '0,
  d_data:   rdata,
  d_user:   '0,
  d_error:  error
};

// outgoing integrity generation
tlul_rsp_intg_gen #(
  .EnableRspIntgGen(EnableRspIntgGen),
  .EnableDataIntgGen(EnableDataIntgGen),
  .UserInIsZero(1'b1)
) u_rsp_intg_gen (
  .tl_i(tl_o_pre),
  .tl_o(tl_o)
);

if (CmdIntgCheck) begin : gen_cmd_intg_check
  logic intg_error_q;
  tlul_cmd_intg_chk u_cmd_intg_chk (
    .tl_i(tl_i),
    .err_o(intg_error)
  );

  assign intg_error_o = intg_error_q;
end else begin : gen_no_cmd_intg_check
  assign intg_error = 1'b0;
  assign intg_error_o = 1'b0;
end

////////////////////
// Error Handling //
////////////////////

// An instruction type transaction is only valid if en_ifetch is enabled
assign instr_error = prim_mubi_pkg::mubi4_test_true_strict(tl_i.a_user.instr_type) &
                     prim_mubi_pkg::mubi4_test_false_loose(en_ifetch_i);

assign err_internal = addr_align_err | tl_err | instr_error | intg_error;

always_comb begin
  if (wr_req) begin
    // Only word-align is accepted based on comportability spec
    addr_align_err = |tl_i.a_address[1:0];
  end else begin
    // No request
    addr_align_err = 1'b0;
  end
end

`include "prim_assert.sv"

/**
 * Tile-Link UL adapter for Register interface with RACL protection
 */

module tlul_adapter_reg_racl
  import tlul_pkg::*;
  import prim_mubi_pkg::mubi4_t;
#(
  parameter  bit CmdIntgCheck      = 0,           // 1: Enable command integrity check
  parameter  bit EnableRspIntgGen  = 0,           // 1: Generate response integrity
  parameter  bit EnableDataIntgGen = 0,           // 1: Generate response data integrity
  parameter  int RegAw             = 8,           // Width of register address
  parameter  int RegDw             = 32,          // Shall be matched with TL_DW
  parameter  int AccessLatency     = 0,           // 0: same cycle, 1: next cycle
  parameter  bit EnableRacl        = 0,           // 1: Enable RACL checks on access
  parameter  bit RaclErrorRsp      = EnableRacl,  // 1: Return TLUL error on RACL errors
  parameter  top_racl_pkg::racl_policy_sel_t RaclPolicySelVec  = 0, // RACL policy for this reg
                                                                    // adapter
  localparam int RegBw             = RegDw/8
) (
  input clk_i,
  input rst_ni,

  // TL-UL interface
  input  tl_h2d_t tl_i,
  output tl_d2h_t tl_o,

  // control interface
  input  mubi4_t  en_ifetch_i,
  output logic    intg_error_o,

  // RACL interface
  input  top_racl_pkg::racl_policy_vec_t racl_policies_i,
  output top_racl_pkg::racl_error_log_t  racl_error_o,

  // Register interface
  output logic             re_o,
  output logic             we_o,
  output logic [RegAw-1:0] addr_o,
  output logic [RegDw-1:0] wdata_o,
  output logic [RegBw-1:0] be_o,
  input                    busy_i,
  // The following two signals are expected
  // to be returned in AccessLatency cycles.
  input        [RegDw-1:0] rdata_i,
  // This can be a write or read error.
  input                    error_i
);
  tl_h2d_t tl_h2d_filtered;
  tl_d2h_t tl_d2h_filtered;

  if (EnableRacl) begin : gen_racl_role_logic
    // Retrieve RACL role from user bits and one-hot encode that for the comparison bitmap
    top_racl_pkg::racl_role_t racl_role;
    assign racl_role = top_racl_pkg::tlul_extract_racl_role_bits(tl_i.a_user.rsvd);

    top_racl_pkg::racl_role_vec_t racl_role_vec;
    prim_onehot_enc #(
      .OneHotWidth( $bits(top_racl_pkg::racl_role_vec_t) )
    ) u_racl_role_encode (
      .in_i ( racl_role     ),
      .en_i ( 1'b1          ),
      .out_o( racl_role_vec )
    );

    logic rd_req, wr_req, racl_read_allowed, racl_write_allowed, racl_error;
    assign rd_req             = tl_i.a_valid & (tl_i.a_opcode == tlul_pkg::Get);
    assign wr_req             = tl_i.a_valid & (tl_i.a_opcode == tlul_pkg::PutFullData |
                                                tl_i.a_opcode == tlul_pkg::PutPartialData);
    assign racl_read_allowed  = (|(racl_policies_i[RaclPolicySelVec].read_perm  & racl_role_vec));
    assign racl_write_allowed = (|(racl_policies_i[RaclPolicySelVec].write_perm & racl_role_vec));
    assign racl_error         = (rd_req & ~racl_read_allowed) | (wr_req & ~racl_write_allowed);
    assign racl_error_o.valid = racl_error & tl_o.a_ready;

    tlul_request_loopback #(
      .ErrorRsp(RaclErrorRsp)
    ) u_loopback (
      .clk_i,
      .rst_ni,
      .squash_req_i ( racl_error      ),
      .tl_h2d_i     ( tl_i            ),
      .tl_d2h_o     ( tl_o            ),
      .tl_h2d_o     ( tl_h2d_filtered ),
      .tl_d2h_i     ( tl_d2h_filtered )
    );

    // Collect RACL error information
    assign racl_error_o.overflow        = 1'b0;
    assign racl_error_o.read_access     = tl_i.a_opcode == tlul_pkg::Get;
    assign racl_error_o.racl_role       = racl_role;
    assign racl_error_o.ctn_uid         = top_racl_pkg::tlul_extract_ctn_uid_bits(tl_i.a_user.rsvd);
    assign racl_error_o.request_address = tl_i.a_address;
  end else begin : gen_no_racl_role_logic
    // Pass through and default assignments
    assign tl_h2d_filtered  = tl_i;
    assign tl_o             = tl_d2h_filtered;
    assign racl_error_o     = '0;
  end

  tlul_adapter_reg #(
    .CmdIntgCheck       (CmdIntgCheck),
    .EnableRspIntgGen   (EnableRspIntgGen),
    .EnableDataIntgGen  (EnableDataIntgGen),
    .RegAw              (RegAw),
    .RegDw              (RegDw),
    .AccessLatency      (AccessLatency)
  ) tlul_adapter_reg (
    .clk_i,
    .rst_ni,
    .tl_i(tl_h2d_filtered),
    .tl_o(tl_d2h_filtered),
    .en_ifetch_i,
    .intg_error_o,
    .re_o,
    .we_o,
    .addr_o,
    .wdata_o,
    .be_o,
    .busy_i,
    .rdata_i,
    .error_i
  );

  // Not all RACL policies are used, even if RACL is enabled
  logic unused_policy;
  assign unused_policy = ^racl_policies_i;

  // Ensure that RACL signals are not undefined
  `ASSERT_KNOWN(RaclAdapterRegErrorKnown_A, racl_error_o.valid)

endmodule

`include "prim_assert.sv"

/**
 * Tile-Link UL adapter for SRAM-like devices
 *
 * - Intentionally omitted BaseAddr in case of multiple memory maps are used in a SoC,
 *   it means that aliasing can happen if target device size in TL-UL crossbar is bigger
 *   than SRAM size
 * - At most one of EnableDataIntgGen / EnableDataIntgPt can be enabled. However it
 *   possible for both to be disabled.
 *   A module can neither generate an integrity response nor pass through any pre-existing
 *   integrity.  This might be the case for non-security critical memories where there is
 *   no stored integrity AND another entity upstream is already generating returning integrity.
 *   There is however no case where EnableDataIntgGen and EnableDataIntgPt are both true.
 */
module tlul_adapter_sram
  import tlul_pkg::*;
  import prim_mubi_pkg::mubi4_t;
#(
  parameter int SramAw            = 12,
  parameter int SramDw            = 32, // Must be multiple of the TL width
  parameter int Outstanding       = 1,  // Only one request is accepted
  parameter int SramBusBankAW     = 12, // SRAM bus address width of the SRAM bank. Only used
                                        // when DataXorAddr=1.
  parameter bit ByteAccess        = 1,  // 1: Enables sub-word write transactions. Note that this
                                        //    results in read-modify-write operations for integrity
                                        //    re-generation if EnableDataIntgPt is set to 1.
  parameter bit ErrOnWrite        = 0,  // 1: Writes not allowed, automatically error
  parameter bit ErrOnRead         = 0,  // 1: Reads not allowed, automatically error
  parameter bit CmdIntgCheck      = 0,  // 1: Enable command integrity check
  parameter bit EnableRspIntgGen  = 0,  // 1: Generate response integrity
  parameter bit EnableDataIntgGen = 0,  // 1: Generate response data integrity
  parameter bit EnableDataIntgPt  = 0,  // 1: Passthrough command/response data integrity
  parameter bit SecFifoPtr        = 0,  // 1: Duplicated fifo pointers
  parameter bit EnableReadback    = 0,  // 1: Readback and check written/read data.
  parameter bit DataXorAddr       = 0,  // 1: XOR data and address for address protection
  localparam int WidthMult        = SramDw / top_pkg::TL_DW,
  localparam int IntgWidth        = tlul_pkg::DataIntgWidth * WidthMult,
  localparam int DataOutW         = EnableDataIntgPt ? SramDw + IntgWidth : SramDw
) (
  input   clk_i,
  input   rst_ni,

  // TL-UL interface
  input   tl_h2d_t          tl_i,
  output  tl_d2h_t          tl_o,

  // control interface
  input   mubi4_t en_ifetch_i,

  // SRAM interface
  output logic                 req_o,
  output mubi4_t               req_type_o,
  input                        gnt_i,
  output logic                 we_o,
  output logic [SramAw-1:0]    addr_o,
  output logic [DataOutW-1:0]  wdata_o,
  output logic [DataOutW-1:0]  wmask_o,
  output logic                 intg_error_o,
  output logic [RsvdWidth-1:0] user_rsvd_o,
  input        [DataOutW-1:0]  rdata_i,
  input                        rvalid_i,
  input        [1:0]           rerror_i, // 2 bit error [1]: Uncorrectable, [0]: Correctable
  output logic                 compound_txn_in_progress_o,
  input  mubi4_t               readback_en_i,
  output logic                 readback_error_o,
  input  logic                 wr_collision_i,
  input  logic                 write_pending_i
);

  localparam int SramByte = SramDw/8;
  localparam int DataBitWidth = prim_util_pkg::vbits(SramByte);
  localparam int WoffsetWidth = (SramByte == top_pkg::TL_DBW) ? 1 :
                                DataBitWidth - prim_util_pkg::vbits(top_pkg::TL_DBW);

  logic error_det; // Internal protocol error checker
  logic error_internal; // Internal protocol error checker
  logic wr_attr_error;
  logic instr_error;
  logic wr_vld_error;
  logic rd_vld_error;
  logic rsp_fifo_error;
  logic sramreqfifo_error;
  logic reqfifo_error;
  logic intg_error;
  logic tlul_error;
  logic readback_error;
  logic sram_byte_readback_error;

  // readback check
  logic readback_error_q;
  if (EnableReadback) begin : gen_cmd_readback_check
    assign readback_error = sram_byte_readback_error;

end else begin : gen_no_readback_check
  logic unused_sram_byte_readback_error;
  assign unused_sram_byte_readback_error = sram_byte_readback_error;
  assign readback_error = '0;
  assign readback_error_q = '0;
end

// readback error output is permanent and should be used for alert generation
// or other downstream effects
assign readback_error_o = readback_error | readback_error_q;

// integrity check
if (CmdIntgCheck) begin : gen_cmd_intg_check
  tlul_cmd_intg_chk u_cmd_intg_chk (
    .tl_i(tl_i),
    .err_o (intg_error)
  );
end else begin : gen_no_cmd_intg_check
  assign intg_error = '0;
end

// permanently latch integrity error until reset
logic intg_error_q;

assign intg_error_o = intg_error | rsp_fifo_error | sramreqfifo_error |
    reqfifo_error | intg_error_q;

// wr_attr_error is true if this is a PUT with an unsupported request size or mask. This is only
// possible if ByteAccess is not allowed.
assign wr_attr_error = (ByteAccess == 0) &&
                       (tl_i.a_opcode == PutFullData || tl_i.a_opcode == PutPartialData) &&
                       (tl_i.a_mask != '1 || tl_i.a_size != 2'h2);

// An instruction type transaction is only valid if en_ifetch is enabled
// If the instruction type is completely invalid, also considered an instruction error
assign instr_error = prim_mubi_pkg::mubi4_test_invalid(tl_i.a_user.instr_type) |
                     (prim_mubi_pkg::mubi4_test_true_strict(tl_i.a_user.instr_type) &
                      prim_mubi_pkg::mubi4_test_false_loose(en_ifetch_i));

if (ErrOnWrite == 1) begin : gen_no_writes
  assign wr_vld_error = tl_i.a_opcode != Get;
end else begin : gen_writes_allowed
  assign wr_vld_error = 1'b0;
end

if (ErrOnRead == 1) begin: gen_no_reads
  assign rd_vld_error = tl_i.a_opcode == Get;
end else begin : gen_reads_allowed
  assign rd_vld_error = 1'b0;
end

// tlul protocol check
tlul_err u_err (
  .clk_i,
  .rst_ni,
  .tl_i(tl_i),
  .err_o (tlul_error)
);

// error return is transactional and thus does not used the "latched" intg_err signal
assign error_det = wr_attr_error | wr_vld_error | rd_vld_error | instr_error |
                   tlul_error    | intg_error;

// from sram_byte to adapter logic
tl_h2d_t tl_i_int;
// from adapter logic to sram_byte
tl_d2h_t tl_o_int;
// from sram_byte to rsp_gen
tl_d2h_t tl_out;

// not all parts of tl_i_int are used
logic unused_tl_i_int;
assign unused_tl_i_int = ^tl_i_int;

tlul_rsp_intg_gen #(
  .EnableRspIntgGen(EnableRspIntgGen),
  .EnableDataIntgGen(EnableDataIntgGen),
  .RspIntgInIsZero(1'b1)
) u_rsp_gen (
  .tl_i(tl_out),
  .tl_o
);

// byte handling for integrity
tlul_sram_byte #(
  .EnableIntg(ByteAccess & EnableDataIntgPt & !ErrOnWrite),
  .Outstanding(Outstanding),
  .EnableReadback(EnableReadback)
) u_sram_byte (
  .clk_i,
  .rst_ni,
  .tl_i,
  .tl_o(tl_out),
  .tl_sram_o(tl_i_int),
  .tl_sram_i(tl_o_int),
  .error_i(error_det),
  .error_o(error_internal),
  .alert_o(sram_byte_readback_error),
  .compound_txn_in_progress_o,
  .readback_en_i,
  .wr_collision_i,
  .write_pending_i
);

typedef struct packed {
  logic [top_pkg::TL_DBW-1:0] mask ; // Byte mask within the TL-UL word
  logic [WoffsetWidth-1:0]    woffset ; // Offset of the TL-UL word within the SRAM word
} sram_req_t ;

typedef struct packed {
  logic [SramBusBankAW-1:0] addr; // Address of the request going to the memory.
} sram_req_addr_t ;

typedef enum logic [1:0] {
  OpWrite,
  OpRead,
  OpUnknown
} req_op_e ;

typedef struct packed {
  req_op_e                    op ;
  logic                       error ;
  prim_mubi_pkg::mubi4_t      instr_type;
  logic [top_pkg::TL_SZW-1:0] size ;
  logic [top_pkg::TL_AIW-1:0] source ;
} req_t ;

typedef struct packed {
  logic [top_pkg::TL_DW-1:0] data ;
  logic [DataIntgWidth-1:0]  data_intg ;
  logic                      error ;
} rsp_t ;

localparam int SramReqWidth = $bits(sram_req_t);
localparam int SramReqFifoWidth = SramReqWidth + (DataXorAddr ? SramBusBankAW : 0);
localparam int ReqFifoWidth = $bits(req_t) ;
localparam int RspFifoWidth = $bits(rsp_t) ;

// FIFO signal in case OutStand is greater than 1
// If request is latched, {write, source} is pushed to req fifo.
// Req fifo is popped when D channel is acknowledged (v & r)
// D channel valid is asserted if it is write request or rsp fifo not empty if read.
logic reqfifo_wvalid, reqfifo_wready;
logic reqfifo_rvalid, reqfifo_rready;
req_t reqfifo_wdata,  reqfifo_rdata;

logic sramreqfifo_wvalid, sramreqfifo_wready;
logic sramreqfifo_rready;

// An item in u_sramreqfifo is the request itself, together (if DataXorAddr is nonzero) with some
// bits of the request address. These values are in sram_req_*data and sram_addr_*data, which get
// combined to fifo items in sramreqfifo_*data.
sram_req_t                   sram_req_wdata, sram_req_rdata;
logic [SramBusBankAW-1:0]    sram_addr_wdata, sram_addr_rdata;
logic [SramReqFifoWidth-1:0] sramreqfifo_wdata, sramreqfifo_rdata;

if (DataXorAddr) begin : gen_combine_with_addr
  assign sramreqfifo_wdata = {sram_addr_wdata, sram_req_wdata};
  assign {sram_addr_rdata, sram_req_rdata} = sramreqfifo_rdata;
end else begin : gen_combine_without_addr
  assign sramreqfifo_wdata = sram_req_wdata;
  assign sram_addr_rdata = '0;
  assign sram_req_rdata = sramreqfifo_rdata;
end
logic rspfifo_wvalid, rspfifo_wready;
logic rspfifo_rvalid, rspfifo_rready;
rsp_t rspfifo_wdata,  rspfifo_rdata;

logic a_ack, d_ack, sram_ack;
assign a_ack    = tl_i_int.a_valid & tl_o_int.a_ready ;
assign d_ack    = tl_o_int.d_valid & tl_i_int.d_ready ;
assign sram_ack = req_o        & gnt_i ;

// Valid handling
logic d_valid, d_error;

always_comb begin
  d_valid = 1'b0;

  if (reqfifo_rvalid) begin
    if (reqfifo_rdata.error) begin
      // Return error response. Assume no request went out to SRAM
      d_valid = 1'b1;
    end else if (reqfifo_rdata.op == OpRead) begin
      d_valid = rspfifo_rvalid;
    end else begin
      // Write without error
      d_valid = 1'b1;
    end
  end else begin
    d_valid = 1'b0;
  end
end

always_comb begin
  d_error = 1'b0;

  if (reqfifo_rvalid) begin
    if (reqfifo_rdata.op == OpRead) begin
      d_error = rspfifo_rdata.error | reqfifo_rdata.error;
    end else begin
      d_error = reqfifo_rdata.error;
    end
  end else begin
    d_error = 1'b0;
  end
end

logic vld_rd_rsp;
assign vld_rd_rsp = d_valid & rspfifo_rvalid & (reqfifo_rdata.op == OpRead);
// If the response data is not valid, we set it to an illegal blanking value which is determined
// by whether the current transaction is an instruction fetch or a regular read operation.
logic [top_pkg::TL_DW-1:0] error_blanking_data;
assign error_blanking_data = (prim_mubi_pkg::mubi4_test_true_strict(reqfifo_rdata.instr_type)) ?
                               DataWhenInstrError :
                               DataWhenError;

// Since DataWhenInstrError and DataWhenError can be arbitrary parameters
// we statically calculate the correct integrity values for these parameters here so that
// they do not have to be supplied externally.
logic [top_pkg::TL_DW-1:0] unused_instr, unused_data;
logic [DataIntgWidth-1:0] error_instr_integ, error_data_integ;
tlul_data_integ_enc u_tlul_data_integ_enc_instr (
  .data_i(DataMaxWidth'(DataWhenInstrError)),
  .data_intg_o({error_instr_integ, unused_instr})
);
tlul_data_integ_enc u_tlul_data_integ_enc_data (
  .data_i(DataMaxWidth'(DataWhenError)),
  .data_intg_o({error_data_integ, unused_data})
);

logic [DataIntgWidth-1:0] error_blanking_integ;
assign error_blanking_integ = (prim_mubi_pkg::mubi4_test_true_strict(reqfifo_rdata.instr_type)) ?
                               error_instr_integ :
                               error_data_integ;

logic [top_pkg::TL_DW-1:0] d_data;
assign d_data = (vld_rd_rsp & ~d_error) ? rspfifo_rdata.data   // valid read
                                        : error_blanking_data; // write or TL-UL error

// If this a write response with data fields set to 0, we have to set all ECC bits correctly
// since we are using an inverted Hsiao code.
logic [DataIntgWidth-1:0] data_intg;
assign data_intg = (reqfifo_rdata.error) ? error_blanking_integ    : // TL-UL error
                   (vld_rd_rsp)          ? rspfifo_rdata.data_intg : // valid read
                   prim_secded_pkg::SecdedInv3932ZeroEcc;            // valid write

// When an error is seen on an incoming transaction it gets an immediate response without
// performing an SRAM request. It may be the transaction receives a ready the first cycle it is
// seen, but if not we force a ready the following cycle. This avoids factoring the error
// calculation into the outgoing ready preventing a feedthrough path from the incoming tilelink
// signals to the outgoing tilelink signals.
logic missed_err_gnt_d, missed_err_gnt_q;

// Track whether we've seen an incoming transaction with an error that didn't get a ready
assign missed_err_gnt_d = error_internal & tl_i_int.a_valid & ~tl_o_int.a_ready;

assign tl_o_int = '{
    d_valid  : d_valid ,
    d_opcode : (d_valid && reqfifo_rdata.op != OpRead) ? AccessAck : AccessAckData,
    d_param  : '0,
    d_size   : (d_valid) ? reqfifo_rdata.size : '0,
    d_source : (d_valid) ? reqfifo_rdata.source : '0,
    d_sink   : 1'b0,
    d_data   : d_data,
    d_user   : '{default: '0, data_intg: data_intg},
    d_error  : d_valid && d_error,
    a_ready  : (gnt_i | missed_err_gnt_q) & reqfifo_wready & sramreqfifo_wready
};

// a_ready depends on the FIFO full condition and grant from SRAM (or SRAM arbiter)
// assemble response, including read response, write response, and error for unsupported stuff

// Output to SRAM:
//    Generate request only when no internal error occurs. If error occurs, the request should be
//    dropped and returned error response to the host. So, error to be pushed to reqfifo.
//    In this case, it is assumed the request is granted (may cause ordering issue later?)
assign req_o       = tl_i_int.a_valid & reqfifo_wready & ~error_internal;
assign req_type_o  = tl_i_int.a_user.instr_type;
assign we_o        = tl_i_int.a_valid & (tl_i_int.a_opcode inside {PutFullData, PutPartialData});
assign addr_o      = (tl_i_int.a_valid) ? tl_i_int.a_address[DataBitWidth+:SramAw] : '0;
assign user_rsvd_o = (tl_i_int.a_valid) ? tl_i_int.a_user.rsvd : '0;

// Support SRAMs wider than the TL-UL word width by mapping the parts of the
// TL-UL address which are more fine-granular than the SRAM width to the
// SRAM write mask.
logic [WoffsetWidth-1:0] woffset;
if (top_pkg::TL_DW != SramDw) begin : gen_wordwidthadapt
  assign woffset = tl_i_int.a_address[DataBitWidth-1:prim_util_pkg::vbits(top_pkg::TL_DBW)];
end else begin : gen_no_wordwidthadapt
  assign woffset = '0;
end

// The size of the data/wmask depends on whether passthrough integrity is enabled.
// If passthrough integrity is enabled, the data is concatenated with the integrity passed through
// the user bits.  Otherwise, it is the data only.
localparam int DataWidth = EnableDataIntgPt ? top_pkg::TL_DW + DataIntgWidth : top_pkg::TL_DW;

// Final combined wmask / wdata
logic [WidthMult-1:0][DataWidth-1:0] wmask_combined;
logic [WidthMult-1:0][DataWidth-1:0] wdata_combined;

// Original tlul portion
logic [WidthMult-1:0][top_pkg::TL_DW-1:0] wmask_int;
logic [WidthMult-1:0][top_pkg::TL_DW-1:0] wdata_int;

// Integrity portion
logic [WidthMult-1:0][DataIntgWidth-1:0] wmask_intg;
logic [WidthMult-1:0][DataIntgWidth-1:0] wdata_intg;

always_comb begin
  wmask_int = '0;
  wdata_int = '0;

  if (tl_i_int.a_valid) begin
    for (int i = 0 ; i < top_pkg::TL_DW/8 ; i++) begin
      wmask_int[woffset][8*i +: 8] = {8{tl_i_int.a_mask[i]}};
      wdata_int[woffset][8*i +: 8] = (tl_i_int.a_mask[i] && we_o) ? tl_i_int.a_data[8*i+:8] : '0;
    end
  end
end

always_comb begin
  wmask_intg  = '0;
  wdata_intg  = '0;

  if (tl_i_int.a_valid) begin
    wmask_intg[woffset] = {DataIntgWidth{1'b1}};
    wdata_intg[woffset] = tl_i_int.a_user.data_intg;
  end
end

for (genvar i = 0; i < WidthMult; i++) begin : gen_write_output
  if (EnableDataIntgPt) begin : gen_combined_output
    assign wmask_combined[i] = {wmask_intg[i], wmask_int[i]};
    assign wdata_combined[i] = {wdata_intg[i], wdata_int[i]};
  end else begin : gen_ft_output
    logic unused_w;
    assign wmask_combined[i] = wmask_int[i];
    assign wdata_combined[i] = wdata_int[i];
    assign unused_w = |wmask_intg & |wdata_intg;
  end
end

assign wmask_o = wmask_combined;
assign wdata_o = wdata_combined;

assign reqfifo_wvalid = a_ack ; // Push to FIFO only when granted
assign reqfifo_wdata  = '{
  op:     (tl_i_int.a_opcode != Get) ? OpWrite : OpRead, // To return AccessAck for opcode error
  error:  error_internal,
  instr_type: tl_i_int.a_user.instr_type,
  size:   tl_i_int.a_size,
  source: tl_i_int.a_source
}; // Store the request only. Doesn't have to store data
assign reqfifo_rready = d_ack ;

// push together with ReqFIFO, pop upon returning read
assign sram_req_wdata = '{
  mask    : tl_i_int.a_mask,
  woffset : woffset
};
assign sramreqfifo_wvalid = sram_ack & ~we_o;
assign sramreqfifo_rready = rspfifo_wvalid;

assign rspfifo_wvalid = rvalid_i & reqfifo_rvalid;

assign sram_addr_wdata = tl_i_int.a_address[DataBitWidth+:SramBusBankAW];

// Make sure only requested bytes are forwarded
logic [WidthMult-1:0][DataWidth-1:0] rdata_reshaped;
logic [DataWidth-1:0] rdata_tlword;

// This just changes the array format so that the correct word can be selected by indexing.
assign rdata_reshaped = rdata_i;

if (EnableDataIntgPt) begin : gen_no_rmask

always_comb begin
  // If the read mask is set to zero, all read data is zeroed out by the mask.
  // We have to set the ECC bits accordingly since we are using an inverted Hsiao code.
  rdata_tlword = prim_secded_pkg::SecdedInv3932ZeroWord;
  // Otherwise, if at least one mask bit is nonzero, we are passing through the integrity.
  // In that case we need to feed back the entire word since otherwise the integrity
  // will not calculate correctly.
  if (|sram_req_rdata.mask) begin
    // Select correct word.
    if (DataXorAddr) begin : gen_data_xor_addr
      // When DataXorAddr is enabled, on a read, the address is XORed with the data fetched from
      // the memory in the underlying memory controller (e.g., flash controller). At this point,
      // the address is again removed. If the address in the read transaction has been modified,
      // e.g., due to a fault, rdata now contains faulty data, which is detected by the
      // integrity mechanism.
      rdata_tlword = {
          rdata_reshaped[sram_req_rdata.woffset][DataWidth-1:top_pkg::TL_DW],
          rdata_reshaped[sram_req_rdata.woffset][top_pkg::TL_DW-1:0] ^
              {{(top_pkg::TL_DW-SramBusBankAW){1'b0}}, sram_addr_rdata}
      };
    end else begin: gen_no_data_xor_addr
      rdata_tlword = rdata_reshaped[sram_req_rdata.woffset];
    end
  end
end

always_comb begin
  rmask = '0;
  for (int i = 0 ; i < top_pkg::TL_DW/8 ; i++) begin
    rmask[8*i +: 8] = {8{sram_req_rdata.mask[i]}};
  end
end

  assign rdata_tlword = rdata_reshaped[sram_req_rdata.woffset] & rmask;
end

assign rspfifo_wdata  = '{
  data      : rdata_tlword[top_pkg::TL_DW-1:0],
  data_intg : EnableDataIntgPt ? rdata_tlword[DataWidth-1 -: DataIntgWidth] : '0,
  error     : rerror_i[1] // Only care for Uncorrectable error
};
assign rspfifo_rready = (reqfifo_rdata.op == OpRead & ~reqfifo_rdata.error)
                      ? reqfifo_rready : 1'b0 ;

// This module only cares about uncorrectable errors.
logic unused_rerror;
assign unused_rerror = rerror_i[0];

// FIFO instance: REQ, RSP

// ReqFIFO is to store the Access type to match to the Response data.
//    For instance, SRAM accepts the write request but doesn't return the
//    acknowledge. In this case, it may be hard to determine when the D
//    response for the write data should send out if reads/writes are
//    interleaved. So, to make it in-order (even TL-UL allows out-of-order
//    responses), storing the request is necessary. And if the read entry
//    is write op, it is safe to return the response right away. If it is
//    read request, then D response is waiting until read data arrives.
prim_fifo_sync #(
  .Width       (ReqFifoWidth),
  .Pass        (1'b0),
  .Depth       (Outstanding),
  .NeverClears (1'b1),
  .Secure      (SecFifoPtr)
) u_reqfifo (
  .clk_i,
  .rst_ni,
  .clr_i   (1'b0),
  .wvalid_i(reqfifo_wvalid),
  .wready_o(reqfifo_wready),
  .wdata_i (reqfifo_wdata),
  .rvalid_o(reqfifo_rvalid),
  .rready_i(reqfifo_rready),
  .rdata_o (reqfifo_rdata),
  .full_o  (),
  .depth_o (),
  .err_o   (reqfifo_error)
);

// sramreqfifo:
//    While the ReqFIFO holds the request until it is sent back via TL-UL, the
//    sramreqfifo only needs to hold the mask and word offset until the read
//    data returns from memory.
prim_fifo_sync #(
  .Width             (SramReqFifoWidth),
  .Pass              (1'b0),
  .Depth             (Outstanding),
  .NeverClears       (1'b1),
  .Secure            (SecFifoPtr),
  .OutputZeroIfEmpty (1)
) u_sramreqfifo (
  .clk_i,
  .rst_ni,
  .clr_i   (1'b0),
  .wvalid_i(sramreqfifo_wvalid),
  .wready_o(sramreqfifo_wready),
  .wdata_i (sramreqfifo_wdata),
  .rvalid_o(),
  .rready_i(sramreqfifo_rready),
  .rdata_o (sramreqfifo_rdata),
  .full_o  (),
  .depth_o (),
  .err_o   (sramreqfifo_error)
);

if (!DataXorAddr) begin : gen_no_data_xor_addr_fifo
  // If u_sramreqfifo doesn't contain any address data, nothing will be reading sram_addr_wdata or
  // sram_addr_rdata. Tie them off with an unused signal.
  logic unused_sram_addresses;
  assign unused_sram_addresses = ^{sram_addr_wdata, sram_addr_rdata};
end

// Rationale having #Outstanding depth in response FIFO.
//    In normal case, if the host or the crossbar accepts the response data,
//    response FIFO isn't needed. But if in any case it has a chance to be
//    back pressured, the response FIFO should store the returned data not to
//    lose the data from the SRAM interface. Remember, SRAM interface doesn't
//    have back-pressure signal such as read_ready.
prim_fifo_sync #(
  .Width       (RspFifoWidth),
  .Pass        (1'b1),
  .Depth       (Outstanding),
  .NeverClears (1'b1),
  .Secure      (SecFifoPtr)
) u_rspfifo (
  .clk_i,
  .rst_ni,
  .clr_i   (1'b0),
  .wvalid_i(rspfifo_wvalid),
  .wready_o(rspfifo_wready),
  .wdata_i (rspfifo_wdata),
  .rvalid_o(rspfifo_rvalid),
  .rready_i(rspfifo_rready),
  .rdata_o (rspfifo_rdata),
  .full_o  (),
  .depth_o (),
  .err_o   (rsp_fifo_error)
);

`include "prim_assert.sv"

module tlul_assert #(
  parameter EndpointType = "Device" // can be either "Host" or "Device"
) (
  input clk_i,
  input rst_ni,

  // tile link ports
  input tlul_pkg::tl_h2d_t h2d,
  input tlul_pkg::tl_d2h_t d2h
);

`ifndef VERILATOR
`ifndef SYNTHESIS

`ifdef UVM
  import uvm_pkg::*;
`endif
  import tlul_pkg::*;
  import top_pkg::*;

  //////////////////////////////////
  // check requests and responses //
  //////////////////////////////////

  // There are up to 2**TL_AIW possible source-IDs. Below array "pend_req" has one entry
  // for each source-ID. Each entry has the following fields:
  //  - pend   : is set to 1 to indicate up to 1 pending request for the source ID
  //  - opcode : "Get" requires "AccessAckData" response, "Put*" require "AccessAck"
  //  - size   : d_size of response must match a_size of request
  //  - mask   : is used to allow X for bytes whose mask bit is 0
  typedef struct packed {
    bit                         pend; // set to 1 to indicate a pending request
    tl_a_op_e                   opcode;
    logic [top_pkg::TL_SZW-1:0] size;
    logic [top_pkg::TL_DBW-1:0] mask;
  } pend_req_t;

  pend_req_t [2**TL_AIW-1:0] pend_req;

  // To test TLUL error cases in UVM tests, pass the tlul_assert_en argument in the UVM config db,
  // which will cause disable_sva to be set to 1. This disables some assertions about the
  // well-formedness of the TL input.
  bit disable_sva;

  // We have some assertions below about the behaviour of d2h.d_error. These aren't actually true
  // for the xbar, since it doesn't return d_error for protocol errors. Disable these checks by
  // passing tlul_d_error_assert_en in the UVM config db, which causes disable_d_error_sva to be set
  // to 1.
  bit disable_d_error_sva;

  logic [7:0]  a_mask, d_mask;
  logic [63:0] a_data, d_data;
  assign a_mask = 8'(h2d.a_mask);
  assign a_data = 64'(h2d.a_data);
  assign d_mask = 8'(pend_req[d2h.d_source].mask);
  assign d_data = 64'(d2h.d_data);

always_ff @(negedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    pend_req <= '0;
  end else begin
    if (h2d.a_valid) begin
      // store each request in pend_req array (we use blocking statements below so
      // that we can handle the case where request and response for the same
      // source-ID happen in the same cycle)
      if (d2h.a_ready) begin
        pend_req[h2d.a_source].pend    <= 1;
        pend_req[h2d.a_source].opcode  <= h2d.a_opcode;
        pend_req[h2d.a_source].size    <= h2d.a_size;
        pend_req[h2d.a_source].mask    <= h2d.a_mask;
      end
    end // h2d.a_valid

    if (d2h.d_valid) begin
      // update pend_req array
      if (h2d.d_ready) begin
        pend_req[d2h.d_source].pend <= 0;
      end
    end //d2h.d_valid
  end
end

sequence h2d_pre_S;
  h2d.a_valid;
endsequence

// a_opcode: only 3 opcodes are legal for requests
sequence legalAOpcode_S;
  (h2d.a_opcode === PutFullData) ||
  (h2d.a_opcode === Get) ||
  (h2d.a_opcode === PutPartialData);
endsequence

// a_param is reserved
sequence legalAParam_S;
  h2d.a_param === '0;
endsequence

// a_size: Size shouldn't be greater than the bus width in TL-UL (not in TL-UH)
//         This assertion can be covered by below
//         (a_size must less than or equal to ones of a_mask)

// a_size: 2**a_size must greater than or equal to $countones(a_mask) for PutPartial and Get
sequence sizeGTEMask_S;
  (h2d.a_opcode == PutFullData) || ((1 << h2d.a_size) >= $countones(h2d.a_mask));
endsequence

// a_size: 2**a_size must equal to $countones(a_mask) for PutFull
sequence sizeMatchesMask_S;
  (h2d.a_opcode inside {PutPartialData, Get}) ||
  ((1 << h2d.a_size) === $countones(h2d.a_mask));
endsequence

// a_source: there should be no more than one pending request per each source ID
sequence pendingReqPerSrc_S;
  pend_req[h2d.a_source].pend == 0;
endsequence

// a_address must be aligned to a_size: a_address & ((1 << a_size) - 1) == 0
sequence addrSizeAligned_S;
  (h2d.a_address & ((1 << h2d.a_size)-1)) == '0;
endsequence

// a_mask must be contiguous for Get and PutFullData requests
//    the spec talks about "naturally aligned". Does this mean that bit [0] of
//    mask is always 1? If that's true, then below code could be much simpler.
//    However, the spec shows a timing diagram where bit 0 of mask is 0.
sequence contigMask_pre_S;
  h2d.a_opcode != PutPartialData;
endsequence

sequence contigMask_S;
  $countones(h2d.a_mask ^ {h2d.a_mask[$bits(h2d.a_mask)-2:0], 1'b0}) <= 2;
endsequence

// a_data must be known for opcode == Put*(depending on mask bits)
sequence aDataKnown_pre_S;
  (h2d.a_opcode != Get);
endsequence

sequence aDataKnown_S;

  endsequence

  /////////////////////////////////////////
  // define sequences for request checks //
  /////////////////////////////////////////

  sequence d2h_pre_S;
    d2h.d_valid;
  endsequence

  // d_opcode: if request was Get, then response must be AccessAckData
  sequence respOpcode_S;
    d2h.d_opcode === ((pend_req[d2h.d_source].opcode == Get) ? AccessAckData : AccessAck);
  endsequence

  // d_param is reserved
  sequence legalDParam_S;
    d2h.d_param === '0;
  endsequence

  // d_size must equal the a_size of the corresponding request
  sequence respSzEqReqSz_S;
    d2h.d_size === pend_req[d2h.d_source].size;
  endsequence

  // d_source: each response should have a pending request using same source ID
  sequence respMustHaveReq_S;
    pend_req[d2h.d_source].pend;
  endsequence

// d_data must be known for AccessAckData (depending on mask bits)
  sequence dDataKnown_pre_S;
    d2h.d_opcode == AccessAckData;
  endsequence

  sequence dDataKnown_S;

endsequence

/////////////////////////////////////////
// define sequences for d_error checks //
/////////////////////////////////////////

sequence d_error_pre_S;
  h2d.a_valid && d2h.a_ready;
endsequence

sequence legalAOpcodeErr_S;
  !(h2d.a_opcode inside {PutFullData, Get, PutPartialData});
endsequence

sequence sizeGTEMaskErr_S;
  (1 << h2d.a_size) < $countones(h2d.a_mask);
endsequence

sequence sizeMatchesMaskErr_S;
  (h2d.a_opcode == PutFullData) && ((1 << h2d.a_size) != $countones(h2d.a_mask));
endsequence

sequence addrSizeAlignedErr_S;
  (h2d.a_address & ((1 << h2d.a_size)-1)) != '0;
endsequence

///////////////////////////////////
// assemble properties and check //
///////////////////////////////////

// note: use negedge clk to avoid possible race conditions
// in this case all signals coming from the device side have an assumed property
if (EndpointType == "Host") begin : gen_host
  // h2d
  `ASSERT(legalAOpcode_A,     h2d_pre_S |-> legalAOpcode_S,     !clk_i, !rst_ni || disable_sva)
  `ASSERT(legalAParam_A,      h2d_pre_S |-> legalAParam_S,      !clk_i, !rst_ni)
  `ASSERT(sizeGTEMask_A,      h2d_pre_S |-> sizeGTEMask_S,      !clk_i, !rst_ni || disable_sva)
  `ASSERT(sizeMatchesMask_A,  h2d_pre_S |-> sizeMatchesMask_S,  !clk_i, !rst_ni || disable_sva)
  `ASSERT(pendingReqPerSrc_A, h2d_pre_S |-> pendingReqPerSrc_S, !clk_i, !rst_ni)
  `ASSERT(addrSizeAligned_A,  h2d_pre_S |-> addrSizeAligned_S,  !clk_i, !rst_ni || disable_sva)
  `ASSERT(contigMask_A,       h2d_pre_S and contigMask_pre_S |-> contigMask_S,
        !clk_i, !rst_ni || disable_sva)
  `ASSERT(aDataKnown_A,       h2d_pre_S and aDataKnown_pre_S |-> aDataKnown_S, !clk_i, !rst_ni)
  // d2h
  `ASSUME(respOpcode_M,       d2h_pre_S |-> respOpcode_S,       !clk_i, !rst_ni)
  `ASSUME(legalDParam_M,      d2h_pre_S |-> legalDParam_S,      !clk_i, !rst_ni)
  `ASSUME(respSzEqReqSz_M,    d2h_pre_S |-> respSzEqReqSz_S,    !clk_i, !rst_ni)
  `ASSUME(respMustHaveReq_M,  d2h_pre_S |-> respMustHaveReq_S,  !clk_i, !rst_ni)
  `ASSUME(dDataKnown_M,       d2h_pre_S and dDataKnown_pre_S |-> dDataKnown_S,
        !clk_i, !rst_ni || disable_sva)
// in this case all signals coming from the host side have an assumed property
end else if (EndpointType == "Device") begin : gen_device
  // h2d
  `ASSUME(legalAParam_M,       h2d_pre_S |-> legalAParam_S,      !clk_i, !rst_ni)
  `ASSUME(pendingReqPerSrc_M,  h2d_pre_S |-> pendingReqPerSrc_S, !clk_i, !rst_ni)
  `ASSUME(aDataKnown_M,        h2d_pre_S and aDataKnown_pre_S |-> aDataKnown_S, !clk_i, !rst_ni)
  `ASSUME(contigMask_M,        h2d_pre_S and contigMask_pre_S |-> contigMask_S,
          !clk_i, !rst_ni || disable_sva)
  // d2h
  `ASSERT(respOpcode_A,        d2h_pre_S |-> respOpcode_S,       !clk_i, !rst_ni)
  `ASSERT(legalDParam_A,       d2h_pre_S |-> legalDParam_S,      !clk_i, !rst_ni)
  `ASSERT(respSzEqReqSz_A,     d2h_pre_S |-> respSzEqReqSz_S,    !clk_i, !rst_ni)
  `ASSERT(respMustHaveReq_A,   d2h_pre_S |-> respMustHaveReq_S,  !clk_i, !rst_ni)
  `ASSERT(dDataKnown_A,        d2h_pre_S and dDataKnown_pre_S |-> dDataKnown_S,
        !clk_i, !rst_ni || disable_sva)

  h2d.a_valid)

// d_* should be known when d_valid == 1 (d_opcode, d_param, d_size already covered above)
// This also covers ASSERT_KNOWN of d_valid
`ASSERT_KNOWN_IF(dKnown_A, {d2h.d_source, d2h.d_sink, d2h.d_error, d2h.d_user}, d2h.d_valid)

//  make sure ready is not X after reset
`ASSERT_KNOWN(aReadyKnown_A, d2h.a_ready)
`ASSERT_KNOWN(dReadyKnown_A, h2d.d_ready)

////////////////////////////////////
// SVA coverage //
////////////////////////////////////
`define TLUL_COVER(SEQ) `COVER(``SEQ``_C, ``SEQ``_S, !clk_i, !rst_ni || disable_sva)

// host sends back2back requests
sequence b2bReq_S;
  h2d.a_valid && d2h.a_ready ##1 h2d.a_valid;
endsequence

// device sends back2back responses
sequence b2bRsp_S;
  d2h.d_valid && h2d.d_ready ##1 d2h.d_valid;
endsequence

// host sends back2back requests with same address
// UVM RAL can't issue this scenario, add this cover to make sure it's tested in some other seq
sequence b2bReqWithSameAddr_S;
  bit [top_pkg::TL_AW-1:0] pre_addr;
  (h2d.a_valid && d2h.a_ready, pre_addr = h2d.a_address)
      ##1 h2d.a_valid && pre_addr == h2d.a_address;
endsequence

// a_valid is dropped without a_ready
sequence aValidNotAccepted_S;
  h2d.a_valid && !d2h.a_ready ##1 !h2d.a_valid;
endsequence

// d_valid is dropped without a_ready
sequence dValidNotAccepted_S;
  d2h.d_valid && !h2d.d_ready ##1 !d2h.d_valid;
endsequence

// host uses same source for back2back items
sequence b2bSameSource_S;
  bit [top_pkg::TL_AIW-1:0] pre_source;
  (h2d.a_valid && d2h.a_ready, pre_source = h2d.a_source) ##1 h2d.a_valid[->1]
      ##0 pre_source == h2d.a_source;
endsequence

// a channal content is changed without being accepted
`define TLUL_A_CHAN_CONTENT_CHANGED_WO_ACCEPTED(NAME) \
  sequence a_``NAME``ChangedNotAccepted_S; \
    int pre; \
    (h2d.a_valid && !d2h.a_ready, pre = h2d.a_``NAME``) ##1 h2d.a_valid[->1] \
        ##0 pre != h2d.a_``NAME``; \
  endsequence \
  `TLUL_COVER(a_``NAME``ChangedNotAccepted)

// d channal content is changed without being accepted
`define TLUL_D_CHAN_CONTENT_CHANGED_WO_ACCEPTED(NAME) \
  sequence d_``NAME``ChangedNotAccepted_S; \
    int pre; \
    (d2h.d_valid && !h2d.d_ready, pre = d2h.d_``NAME``) ##1 d2h.d_valid[->1] \
        ##0 pre != d2h.d_``NAME``; \
  endsequence \
  `TLUL_COVER(d_``NAME``ChangedNotAccepted)

if (EndpointType == "Host") begin : gen_host_cov // DUT is host
  `TLUL_COVER(b2bRsp)
  `TLUL_COVER(dValidNotAccepted)

always_ff @(posedge clk_i or negedge rst_ni) begin
  if (!rst_ni) begin
    disable_sva <= 0;
    disable_d_error_sva <= 0;
  end
end

